fn Circle({ r }: { r: f64 }) -> Jsx { <circle r={r} /> }

fn view(s: Shape) -> Jsx {
  match s {
    Circle { r, ... } => <Circle r={r} />,   // パターンに関数は来ないのでバリアント。<Circle /> は関数
    Rect { ... } => <rect />,
    Label { text, ... } => <text>{text}</text>,
  }
}
fn moved(s: Shape, d: Vec2) -> Shape {
  match s { Circle { center, ... } => Circle { ...s, center: add(center) }, … }   // 修飾は要らない
}
// 位置引数のバリアント `Pair(a, b)` と同名の関数 `Pair` があるときだけ、`Shape::Pair(a, b)` と書く
